#ifndef STRING_BLOB_H
#define STRING_BLOB_H

#include <exception>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

class StrBlobPtr;

class StrBlob {
	friend class StrBlobPtr;
	public:
		using size_type = std::vector<std::string>::size_type;
		StrBlob();
		StrBlob(std::initializer_list<std::string> il);
		StrBlobPtr begin() const;  // return StrBlobPtr to the first element
		StrBlobPtr end() const;    // and one past the last element
		size_type size() const { return data->size(); }
		bool empty() const { return data->empty(); }
		// add and remove elements
		void push_back(const std::string &t) { data->push_back(t); }
		void pop_back();
		// element access
		std::string& front();
		std::string& back();
		std::string& front() const;
		std::string& back() const;
	private:
		std::shared_ptr<std::vector<std::string>> data;
		// throws msg if data[i] isn't valid
		void check(size_type i, const std::string &msg) const;
};

// constructors
StrBlob::StrBlob() : data(std::make_shared<std::vector<std::string>>()) {}
StrBlob::StrBlob(std::initializer_list<std::string> il) :
	data(std::make_shared<std::vector<std::string>>(il)) {}

// members
void StrBlob::check(size_t i, const std::string &msg) const
{
	if (i >= data->size())
		throw std::out_of_range(msg);
}

void StrBlob::pop_back()
{
	check(0, "back on empty StrBlob");
	data->pop_back();
}

std::string& StrBlob::front()
{
	check(0, "front on empty StrBlob");
	return data->front();
}

std::string& StrBlob::front() const
{
	check(0, "front on empty StrBlob");
	return data->front();
}

std::string& StrBlob::back()
{
	check(0, "back on empty StrBlob");
	return data->back();
}

std::string& StrBlob::back() const
{
	check(0, "back on empty StrBlob");
	return data->back();
}

// StrBlobPtr throws an exception on attempts to access a nonexistent element
class StrBlobPtr {
	public:
		StrBlobPtr() : curr(0) {}
		StrBlobPtr(const StrBlob &a, size_t sz = 0) :
			wptr(a.data), curr(sz) {}
		std::string& deref() const;
		StrBlobPtr& incr();    // prefix version
	private:
		// check returns a shared_ptr to the vector if the check succeeds
		std::shared_ptr<std::vector<std::string>>
			check(std::size_t, const std::string &) const;
		// store a weak_ptr, which means the underlying vector might be destroyed
		std::weak_ptr<std::vector<std::string>> wptr;
		size_t curr;            // current position within the array
};

std::shared_ptr<std::vector<std::string>>
StrBlobPtr::check(std::size_t i, const std::string &msg) const
{
	auto ret = wptr.lock();     // is the vector still around
	if (!ret)
		throw std::runtime_error("unbound StrBlobPtr");
	if (i >= ret->size())
		throw std::out_of_range(msg);
	return ret;     // otherwise, return a shared_ptr to the vector
}

std::string&
StrBlobPtr::deref() const
{
	auto p = check(curr, "dereference past end");
	return (*p)[curr];  // (*p) is the vector to which this object points

}

// prefix: return a reference to the increment object
StrBlobPtr&
StrBlobPtr::incr()
{
	//if curr already points past the end of the container, can't increment it
	check(curr, "increment past end of StrBlobPtr");
	++curr;
	return *this;
}

// these members can't be defined until StrStrBlob and StrBlobPtr are defined.
StrBlobPtr StrBlob::begin() const { return StrBlobPtr(*this); }
StrBlobPtr StrBlob::end() const { return StrBlobPtr(*this, data->size()); }
#endif

#ifndef TEXT_QUERY_H
#define TEXT_QUERY_H

#include <fstream>
#include <map>
#include <memory>
#include <set>
#include <sstream>
#include <vector>

class QueryResult;
class TextQuery {
	public:
		using line_no = std::vector<std::string>::size_type;
		TextQuery(std::ifstream &);
		QueryResult query (const std::string &) const;
	private:
		std::shared_ptr<std::vector<std::string>> text;
		std::map<std::string, std::shared_ptr<std::set<line_no>>> words_map;
};

class QueryResult {
	friend std::ostream& print(std::ostream &, const QueryResult &);
	public:
		QueryResult(std::shared_ptr<std::vector<std::string>> p,
				    std::shared_ptr<std::set<TextQuery::line_no>> ln,
					std::string w, unsigned n) :
			text(p), lines(ln), sought(w), count(n) {}
	private:
		std::shared_ptr<std::vector<std::string>> text;
		std::shared_ptr<std::set<TextQuery::line_no>> lines;
		std::string sought;
		unsigned count = 0;
};

// constructors
TextQuery::TextQuery(std::ifstream &infile) :
	text(std::make_shared<std::vector<std::string>>())
{
	std::string line, word;
	for (size_t lineNumber = 1; getline(infile, line); ++lineNumber) {
		text->push_back(line);
		std::istringstream iss(line);
		while (iss >> word) {
			auto &lines = words_map[word];
			if (!lines)
				lines = std::make_shared<std::set<line_no>>();
			lines->insert(lineNumber);
		}
	}
}

// members
QueryResult
TextQuery::query(const std::string &s) const
{
	static auto notFound = std::make_shared<std::set<line_no>>();
	auto pos = words_map.find(s);
	if (pos == words_map.end())
		return {text, notFound, s, 0};
	unsigned count = 0;
	std::string word;
	for (auto const &line : *text) {
		std::istringstream iss(line);
		while (iss >> word)
			if (word == s)
				++count;
	}
	return {text, pos->second, s, count}; 
}

// non-members
std::ostream&
print(std::ostream &os, const QueryResult &result)
{
	os << result.sought << " occurs " << result.count
	   << ((result.count > 1) ? " times" : " time") << std::endl;
	for (auto const &n : *result.lines)
		os << "\t(line " << n << ") " << result.text->at(n - 1) << '\n';
	return os;
}
#endif
